                    $brace += ($lines[$j] =~ tr/{/{/);
                    $brace -= ($lines[$j] =~ tr/}//);
                    last if $brace > 0;
                }
            }
            while ($j < @lines && $brace > 0) {
                $j++;
                next if $j >= @lines;
                $brace += ($lines[$j] =~ tr/{/{/);
                $brace -= ($lines[$j] =~ tr/}//);
            }
            my $end = $j + 1;

            my $qualified = $recv_type ? "$pkg.$recv_type.$name" : "$pkg.$name";
            push @funcs, {
                name => $name,
                recv_type => $recv_type,
                start => $start,
                end => $end,
                qualified => $qualified,
                pkg => $pkg,
                file => $file,
            };
            $i = $j + 1;
            next;
        }
        $i++;
    }

    $file_info{$file} = { package => $pkg, funcs => \@funcs, lines => \@lines };

    if (is_internal_decl_file($file)) {
        push @internal_symbols, @funcs;
    }
}

sub parse_imports {
    my ($file) = @_;
    my $lines = $file_info{$file}{lines};
    my %imports;
    my $in_import = 0;
    for my $line (@$lines) {
        if ($line =~ /^import\s+"([^"]+)"/) {
            my $path = $1;
            my $local = (split m{/}, $path)[-1];
            $local =~ s/[^a-zA-Z0-9_]/_/g;
            $imports{$path} = $local;
            next;
        }
        if ($line =~ /^import\s+\(/) { $in_import = 1; next; }
        if ($in_import) {
            if ($line =~ /^\)/) { $in_import = 0; next; }
            if ($line =~ /^\s*"([^"]+)"/) {
                my $path = $1;
                my $local = (split m{/}, $path)[-1];
                $local =~ s/[^a-zA-Z0-9_]/_/g;
                $imports{$path} = $local;
            } elsif ($line =~ /^\s+(\w+)\s+"([^"]+)"/) {
                $imports{$2} = $1;
            }
        }
    }
    return \%imports;
}

my %fanin;
my %sym_by_key;

for my $sym (@internal_symbols) {
    my $q = $sym->{qualified};
    $fanin{$q} = { callers => {}, call_sites => 0, sym => $sym };
    $sym_by_key{$q} = $sym;
}

sub enclosing_func {
    my ($file, $line_num) = @_;
    my $funcs = $file_info{$file}{funcs} // [];
    for my $f (@$funcs) {
        if ($line_num >= $f->{start} && $line_num <= $f->{end}) {
            my $caller_q = "$file_info{$file}{package}.$f->{name}";
            $caller_q = "$file_info{$file}{package}.$f->{recv_type}.$f->{name}" if $f->{recv_type};
            return "$file:$caller_q";
        }
    }
    return "$file:TOPLEVEL";
}

my %path_to_pkg;
for my $file (@all_go_files) {
    next unless $file =~ m{^$REPO/internal/};
    my $rel = $file; $rel =~ s{^$REPO/}{}; $rel =~ s{/[^/]+$}{};
    my $pkg = $file_info{$file}{package};
    $path_to_pkg{"github.com/usememos/memos/$rel"} = $pkg;
}

my %pkg_func_to_q;
my %method_to_q;
for my $sym (@internal_symbols) {
    if ($sym->{recv_type}) {
        push @{$method_to_q{$sym->{name}}}, $sym->{qualified};
    } else {
        $pkg_func_to_q{"$sym->{pkg}.$sym->{name}"} = $sym->{qualified};
    }
}

for my $file (@all_go_files) {
    my $lines = $file_info{$file}{lines};
    my $imports = parse_imports($file);

    my %local_info;
    for my $path (keys %$imports) {
        next unless $path =~ m{github\.com/usememos/memos/internal/};
        my $pkg = $path_to_pkg{$path};
        next unless $pkg;
        $local_info{$imports->{$path}} = { path => $path, pkg => $pkg };
    }

    my $caller_pkg = $file_info{$file}{package};
    my $file_dir = dirname($file);

    for my $line_idx (0 .. $#$lines) {
        my $line = $lines->[$line_idx];
        my $line_num = $line_idx + 1;
        next if $line =~ /^func\s+/;

        while ($line =~ /\b(\w+)\.(\w+)\s*\(/g) {
            my ($local, $fname) = ($1, $2);
            next unless exists $local_info{$local};
            my $pkg = $local_info{$local}{pkg};
            my $key = "$pkg.$fname";
            next unless exists $pkg_func_to_q{$key};
            my $q = $pkg_func_to_q{$key};
            my $sym = $sym_by_key{$q};
            next if $file eq $sym->{file} && $line_num == $sym->{start};
            my $caller = enclosing_func($file, $line_num);
            $fanin{$q}{callers}{$caller} = 1;
            $fanin{$q}{call_sites}++;
        }

        for my $sym (@internal_symbols) {
            next if $sym->{recv_type};
            next unless dirname($file) eq dirname($sym->{file}) && $caller_pkg eq $sym->{pkg};
            my $name = $sym->{name};
            if ($line =~ /(?<![.\w])\Q$name\E\s*\(/ && $line !~ /^func\s/) {
                my $q = $sym->{qualified};
                next if $file eq $sym->{file} && $line_num == $sym->{start};
                next if $line =~ /\.\Q$name\E\s*\(/;
                my $caller = enclosing_func($file, $line_num);
                $fanin{$q}{callers}{$caller} = 1;
                $fanin{$q}{call_sites}++;
            }
        }

        while ($line =~ /\.(\w+)\s*\(/g) {
            my $mname = $1;
            next unless exists $method_to_q{$mname};
            my @candidates = @{$method_to_q{$mname}};
            my @matched;
            for my $q (@candidates) {
                my $sym = $sym_by_key{$q};
                my $rtype = $sym->{recv_type};
                if (@candidates == 1) {
                    push @matched, $q;
                } elsif ($line =~ /\b\Q$rtype\E\b/) {
                    push @matched, $q;
                }
            }
            if (@matched == 0 && @candidates == 1) {
                @matched = @candidates;
            }
            next if @matched != 1;
            my $q = $matched[0];
            my $sym = $sym_by_key{$q};
            next if $file eq $sym->{file} && $line_num == $sym->{start};
            my $caller = enclosing_func($file, $line_num);
            $fanin{$q}{callers}{$caller} = 1;
            $fanin{$q}{call_sites}++;
        }
    }
}

my @ranked = sort {
    (scalar keys %{$fanin{$b}{callers}}) <=> (scalar keys %{$fanin{$a}{callers}})
    || $fanin{$b}{call_sites} <=> $fanin{$a}{call_sites}
} keys %fanin;

print "=== TOP 40 BY DISTINCT CALLER COUNT (FAN-IN) ===\n";
my $n = 0;
for my $q (@ranked) {
    last if ++$n > 40;
    my $fi = $fanin{$q};
    my $nc = scalar keys %{$fi->{callers}};
    next if $nc == 0;
    my $sym = $fi->{sym};
    print sprintf("%4d callers | %4d sites | %s | %s\n", $nc, $fi->{call_sites}, $q, $sym->{file});
}

print "\n=== TOP 40 BY CALL SITE COUNT ===\n";
@ranked = sort { $fanin{$b}{call_sites} <=> $fanin{$a}{call_sites} } keys %fanin;
$n = 0;
for my $q (@ranked) {
    last if ++$n > 40;
    my $fi = $fanin{$q};
    next if $fi->{call_sites} == 0;
    my $sym = $fi->{sym};
    print sprintf("%4d sites | %4d callers | %s | %s\n", $fi->{call_sites}, scalar keys %{$fi->{callers}}, $q, $sym->{file});
}

