    my $fi = $fanin{$top};
    print "Declaration: $fi->{sym}{file}:$fi->{sym}{start}\n";
    print "Callers (" . (scalar keys %{$fi->{callers}}) . "):\n";
    for my $c (sort keys %{$fi->{callers}}) {
        print "  $c\n";
    }
}

print "\nTotal internal symbols: " . scalar(@internal_symbols) . "\n";

