BEGIN {
    repo = "/bench/repo"
}
/^FILE:/ {
    file = substr($0, 6)
    pkg = ""
    delete funcs
    nfuncs = 0
    next
}
/^package / {
    pkg = $2
    file_pkg[file] = pkg
    next
}
/^func / {
    recv = ""
    fname = ""
    if (match($0, /^func \(([^)]*)\)[[:space:]]+([A-Za-z0-9_]+)[[:space:]]*\(/, m)) {
        recv = m[1]
        fname = m[2]
    } else if (match($0, /^func ([A-Za-z0-9_]+)[[:space:]]*\(/, m)) {
        fname = m[1]
    } else {
        next
    }
    rtype = ""
    if (recv ~ /\*/) {
        tmp = recv
        sub(/^.*\*/, "", tmp)
        sub(/[^A-Za-z0-9_].*/, "", tmp)
        rtype = tmp
    } else if (recv != "") {
        tmp = recv
        sub(/[^A-Za-z0-9_].*/, "", tmp)
        rtype = tmp
    }
    nfuncs++
    funcs[nfuncs] = fname
    func_start[nfuncs] = NR
    func_recv[nfuncs] = rtype
    func_pkg[nfuncs] = pkg
    func_file[nfuncs] = file

    if (file ~ repo "/internal/" && file !~ /_test\.go$/ && file !~ /\/internal\/testutil\//) {
        qual = (rtype ? pkg "." rtype "." fname : pkg "." fname)
        is_internal[qual] = 1
        sym_name[qual] = fname
        sym_recv[qual] = rtype
        sym_pkg[qual] = pkg
        sym_file[qual] = file
        sym_start[qual] = NR
        if (rtype == "") {
            pkg_func[sym_pkg[qual] SUBSEP fname] = qual
        } else {
            method_list[fname] = method_list[fname] (method_list[fname] ? "\t" : "") qual
            method_count[fname]++
        }
    }
    next
}
{
    # track func end implicitly via next func start or EOF - handled in END via line numbers
}
END {
    # second pass needed - this script only collects decls
}

