args.command:
awk -f /dev/stdin /dev/null <<'AWKSCRIPT'
BEGIN {
    repo = "/bench/repo"
    nfiles = 0
    while ((getline line < "/tmp/go_files.txt") > 0) {
        files[++nfiles] = line
    }
    close("/tmp/go_files.txt")
}
function read_file(f,    i, cmd) {
    delete lines; nlines = 0
    while ((getline lines[++nlines] < f) > 0) {}
    close(f)
}
function parse_decls(f,    i, pkg, fname, recv, rtype, qual, tmp) {
    pkg = ""
    for (i = 1; i <= nlines; i++) {
        if (lines[i] ~ /^package /) { split(lines[i], a, " "); pkg = a[2] }
        if (lines[i] ~ /^func /) {
            recv = ""; fname = ""
            if (match(lines[i], /^func \(([^)]*)\)[[:space:]]+([A-Za-z0-9_]+)[[:space:]]*\(/, m)) {
                recv = m[1]; fname = m[2]
            } else if (match(lines[i], /^func ([A-Za-z0-9_]+)[[:space:]]*\(/, m)) {
                fname = m[1]
            } else continue
            rtype = ""
            if (recv ~ /\*/) { tmp=recv; sub(/^.*\*/, "", tmp); sub(/[^A-Za-z0-9_].*/, "", tmp); rtype=tmp }
            else if (recv != "") { tmp=recv; sub(/[^A-Za-z0-9_].*/, "", tmp); rtype=tmp }
            qual = (rtype ? pkg "." rtype "." fname : pkg "." fname)
            file_funcs[f, ++file_nfuncs[f]] = qual "|" fname "|" rtype "|" pkg "|" i
            file_func_start[f, file_nfuncs[f]] = i
            if (f ~ repo "/internal/" && f !~ /_test\.go$/ && f !~ /\/internal\/testutil\//) {
                is_internal[qual] = 1
                sym_name[qual]=fname; sym_recv[qual]=rtype; sym_pkg[qual]=pkg
                sym_file[qual]=f; sym_start[qual]=i
                if (rtype == "") pkg_func[sym_pkg[qual] SUBSEP fname] = qual
                else { mc[fname]++; mlist[fname, mc[fname]] = qual }
            }
        }
    }
    file_pkg[f] = pkg
}
function parse_imports(f,    i, inblock, path, local) {
    inblock = 0
    for (i = 1; i <= nlines; i++) {
        if (lines[i] ~ /^import \(/ ) { inblock = 1; continue }
        if (inblock && lines[i] ~ /^\)/) { inblock = 0; continue }
        if (lines[i] ~ /^import "/) {
            if (match(lines[i], /"([^"]+)"/, m)) {
                path = m[1]
                if (path ~ /github\.com\/usememos\/memos\/internal\//) {
                    local = path; sub(/.*\//, "", local); gsub(/[^A-Za-z0-9_]/, "_", local)
                    import_local[f SUBSEP path] = local
                }
            }
        }
        if (inblock) {
            if (match(lines[i], /([A-Za-z0-9_]+)[[:space:]]+"([^"]+)"/, m)) {
                path = m[2]; local = m[1]
                if (path ~ /github\.com\/usememos\/memos\/internal\//)
                    import_local[f SUBSEP path] = local
            } else if (match(lines[i], /"([^"]+)"/, m)) {
                path = m[1]
                if (path ~ /github\.com\/usememos\/memos\/internal\//) {
                    local = path; sub(/.*\//, "", local); gsub(/[^A-Za-z0-9_]/, "_", local)
                    import_local[f SUBSEP path] = local
                }
            }
        }
    }
}
function path_to_pkg(path,    d, cmd, p) {
    if (path in path_pkg) return path_pkg[path]
    gsub(/github\.com\/usememos\/memos\//, repo "/", path)
    d = path
    cmd = "awk '/^package /{print $2; exit}' " d "/*.go 2>/dev/null | head -1"
    cmd | getline p; close(cmd)
    path_pkg[path] = p
    return p
}
function enclosing(f, ln,    j, q) {
    q = f ":TOPLEVEL"
    for (j = 1; j <= file_nfuncs[f]; j++) {
        split(file_funcs[f, j], p, "|")
        if (ln >= file_func_start[f,j]) q = f ":" p[4] "." (p[3] ? p[3] "." : "") p[2]
    }
    return q
}
function record_call(q, f, ln,    c) {
    if (sym_file[q] == f && ln == sym_start[q]) return
    c = enclosing(f, ln)
    if (!(q SUBSEP c in seen_caller)) {
        seen_caller[q SUBSEP c] = 1
        fanin_c[q]++
    }
    fanin_s[q]++
}
END {
    # Pass 1: declarations
    for (fi = 1; fi <= nfiles; fi++) {
        f = files[fi]
        read_file(f)
        parse_decls(f)
        parse_imports(f)
    }
    # Build path->pkg from internal dirs
    for (fi = 1; fi <= nfiles; fi++) {
        f = files[fi]
        if (f !~ repo "/internal/") continue
        d = f; sub(/\/[^\/]+$/, "", d)
        rel = d; sub("^" repo "/", "", rel)
        path_pkg["github.com/usememos/memos/" rel] = file_pkg[f]
    }
    # Pass 2: call sites
    for (fi = 1; fi <= nfiles; fi++) {
        f = files[fi]
        read_file(f)
        cpkg = file_pkg[f]
        fdir = f; sub(/\/[^\/]+$/, "", fdir)
        for (i = 1; i <= nlines; i++) {
            line = lines[i]
            if (line ~ /^func /) continue
            # qualified calls
            pos = 1
            while (match(substr(line, pos), /\b([A-Za-z0-9_]+)\.([A-Za-z0-9_]+)[[:space:]]*\(/, m)) {
                local = m[1]; fname = m[2]
                start = pos + RSTART - 1
                pos = start + RLENGTH
                # find if local is internal import
                for (k in import_local) {
                    split(k, kk, SUBSEP)
                    if (kk[1] != f) continue
                    if (import_local[k] == local) {
                        ipath = kk[2]
                        ipkg = path_pkg[ipath]
                        if (ipkg == "") continue
                        key = ipkg SUBSEP fname
                        if (key in pkg_func) record_call(pkg_func[key], f, i)
                    }
                }
            }
            # same-package unqualified
            for (q in is_internal) {
                if (sym_recv[q] != "") continue
                if (sym_file[q] !~ "^" fdir "/") continue
                if (sym_pkg[q] != cpkg) continue
                fname = sym_name[q]
                if (line ~ ("(^|[^A-Za-z0-9_.])" fname "[[:space:]]*\\(") && line !~ /^func /) {
                    if (line ~ ("\\." fname "[[:space:]]*\\(")) continue
                    record_call(q, f, i)
                }
            }
            # methods - only unambiguous names
            pos = 1
            while (match(substr(line, pos), /\.([A-Za-z0-9_]+)[[:space:]]*\(/, m)) {
                mname = m[1]
                start = pos + RSTART - 1
                pos = start + RLENGTH
                if (!(mname in mc) || mc[mname] != 1) continue
                q = mlist[mname, 1]
                record_call(q, f, i)
            }
        }
    }
    # Also handle ambiguous methods with manual high-value ones
    # Re-scan for common methods with receiver type hints
    amb_methods["Render"] = 1
    amb_methods["Validate"] = 1
    amb_methods["Parse"] = 1
    for (fi = 1; fi <= nfiles; fi++) {
        f = files[fi]
        read_file(f)
        for (i = 1; i <= nlines; i++) {
            line = lines[i]
            if (line ~ /^func /) continue
            for (mname in amb_methods) {
                if (mc[mname] <= 1) continue
                pos = 1
                while (match(substr(line, pos), "\\." mname "[[:space:]]*\\(", mm)) {
                    start = pos + RSTART - 1
                    pos = start + RLENGTH
                    for (j = 1; j <= mc[mname]; j++) {
                        q = mlist[mname, j]
                        rtype = sym_recv[q]
                        if (line ~ rtype) record_call(q, f, i)
                    }
                }
            }
        }
    }
    # Output
    nout = 0
    for (q in is_internal) {
        if (fanin_c[q] > 0) {
            out[nout++] = fanin_c[q] SUBSEP fanin_s[q] SUBSEP q SUBSEP sym_file[q]
        }
    }
    for (i = 0; i < nout; i++) {
        for (j = i+1; j < nout; j++) {
            split(out[i], ai, SUBSEP); split(out[j], aj, SUBSEP)
            if (aj[1]+0 > ai[1]+0 || (aj[1]+0 == ai[1]+0 && aj[2]+0 > ai[2]+0)) {
                tmp = out[i]; out[i] = out[j]; out[j] = tmp
            }
        }
    }
    print "=== TOP 40 BY DISTINCT CALLERS (FAN-IN) ==="
    for (i = 0; i < nout && i < 40; i++) {
        split(out[i], a, SUBSEP)
        print a[1] " callers | " a[2] " sites | " a[3] " | " a[4]
    }
    print "\nTotal internal symbols: " length(is_internal)
    print "Symbols with >=1 caller: " nout
}
AWKSCRIPT

