                if (line ~ ("(^|[^A-Za-z0-9_.])" fname "[[:space:]]*\\(") && line !~ /^func /) {
                    if (line ~ ("\\." fname "[[:space:]]*\\(")) continue
                    record_call(q, f, i)
                }
            }
            # methods - only unambiguous names
            pos = 1
            while (match(substr(line, pos), /\.([A-Za-z0-9_]+)[[:space:]]*\(/, m)) {
                mname = m[1]
                start = pos + RSTART - 1
                pos = start + RLENGTH
                if (!(mname in mc) || mc[mname] != 1) continue
                q = mlist[mname, 1]
                record_call(q, f, i)
            }
        }
    }
    # Also handle ambiguous methods with manual high-value ones
    # Re-scan for common methods with receiver type hints
    amb_methods["Render"] = 1
    amb_methods["Validate"] = 1
    amb_methods["Parse"] = 1
    for (fi = 1; fi <= nfiles; fi++) {
        f = files[fi]
        read_file(f)
        for (i = 1; i <= nlines; i++) {
            line = lines[i]
            if (line ~ /^func /) continue
            for (mname in amb_methods) {
                if (mc[mname] <= 1) continue
                pos = 1
                while (match(substr(line, pos), "\\." mname "[[:space:]]*\\(", mm)) {
                    start = pos + RSTART - 1
                    pos = start + RLENGTH
                    for (j = 1; j <= mc[mname]; j++) {
                        q = mlist[mname, j]
                        rtype = sym_recv[q]
                        if (line ~ rtype) record_call(q, f, i)
                    }
                }
            }
        }
    }
    # Output
    nout = 0
    for (q in is_internal) {
        if (fanin_c[q] > 0) {
            out[nout++] = fanin_c[q] SUBSEP fanin_s[q] SUBSEP q SUBSEP sym_file[q]
        }
    }
    for (i = 0; i < nout; i++) {
        for (j = i+1; j < nout; j++) {
            split(out[i], ai, SUBSEP); split(out[j], aj, SUBSEP)
            if (aj[1]+0 > ai[1]+0 || (aj[1]+0 == ai[1]+0 && aj[2]+0 > ai[2]+0)) {
                tmp = out[i]; out[i] = out[j]; out[j] = tmp
            }
        }
    }
    print "=== TOP 40 BY DISTINCT CALLERS (FAN-IN) ==="
    for (i = 0; i < nout && i < 40; i++) {
        split(out[i], a, SUBSEP)
        print a[1] " callers | " a[2] " sites | " a[3] " | " a[4]
    }
    print "\nTotal internal symbols: " length(is_internal)
    print "Symbols with >=1 caller: " nout
}
