args.streamContent:
BEGIN {
    repo = "/bench/repo"
    nfiles = 0
    while ((getline line < "/tmp/go_files.txt") > 0) files[++nfiles] = line
    close("/tmp/go_files.txt")
}
function trim(s) { sub(/^[ \t]+/, "", s); sub(/[ \t]+$/, "", s); return s }
function first_word(s,   w) { split(s, w, /[ \t(]+/); return w[1] }
function read_file(f,   i) {
    nlines = 0
    while ((getline lines[++nlines] < f) > 0) {}
    close(f)
}
function parse_func_line(line,   i, rest) {
    if (line ~ /^func \(/ ) {
        sub(/^func \(/, "", line)
        i = index(line, ")")
        recv = substr(line, 1, i-1)
        rest = substr(line, i+1)
        fname = first_word(trim(rest))
        rtype = recv
        sub(/^[^*]*\*/, "", rtype)
        sub(/[^A-Za-z0-9_].*/, "", rtype)
        if (index(recv, "*") == 0) sub(/[^A-Za-z0-9_].*/, "", rtype)
        return 1
    }
    if (line ~ /^func /) {
        sub(/^func /, "", line)
        fname = first_word(line)
        recv = ""; rtype = ""
        return 1
    }
    return 0
}
function parse_decls(f,   i, pkg, qual) {
    pkg = ""
    file_nfuncs[f] = 0
    for (i = 1; i <= nlines; i++) {
        if (lines[i] ~ /^package /) pkg = $2
        if (parse_func_line(lines[i])) {
            file_nfuncs[f]++
            j = file_nfuncs[f]
            file_func_name[f,j] = fname
            file_func_recv[f,j] = rtype
            file_func_start[f,j] = i
            file_func_pkg[f,j] = pkg
            qual = (rtype ? pkg "." rtype "." fname : pkg "." fname)
            file_func_qual[f,j] = qual
            if (f ~ repo "/internal/" && f !~ /\/internal\/testutil\//) {
                is_internal[qual] = 1
                sym_name[qual] = fname
                sym_recv[qual] = rtype
                sym_pkg[qual] = pkg
                sym_file[qual] = f
                sym_start[qual] = i
                if (rtype == "") {
                    pkg_func[sym_pkg[qual] SUBSEP fname] = qual
                } else {
                    mc[fname]++
                    mlist[fname SUBSEP mc[fname]] = qual
                }
            }
        }
    }
    file_pkg[f] = pkg
}
function parse_imports(f,   i, inblock, path, local) {
    inblock = 0
    for (i = 1; i <= nlines; i++) {
        if (lines[i] ~ /^import \(/ ) { inblock = 1; continue }
        if (inblock && lines[i] ~ /^\)/) { inblock = 0; continue }
        if (lines[i] ~ /^import "/) {
            if (match(lines[i], /"[^"]+"/)) {
                path = substr(lines[i], RSTART+1, RLENGTH-2)
                if (path ~ /github\.com\/usememos\/memos\/internal\//) {
                    local = path; sub(/.*\//, "", local); gsub(/[^A-Za-z0-9_]/, "_", local)
                    imp_pkg[f SUBSEP local] = path
                }
            }
        }
        if (inblock) {
            if (match(lines[i], /[A-Za-z0-9_]+[ \t]+"[^"]+"/)) {
                chunk = substr(lines[i], RSTART, RLENGTH)
                split(chunk, parts, "\"")
                local = trim(parts[1])
                path = parts[2]
                if (path ~ /github\.com\/usememos\/memos\/internal\//)
                    imp_pkg[f SUBSEP local] = path
            } else if (match(lines[i], /"[^"]+"/)) {
                path = substr(lines[i], RSTART+1, RLENGTH-2)
                if (path ~ /github\.com\/usememos\/memos\/internal\//) {
                    local = path; sub(/.*\//, "", local); gsub(/[^A-Za-z0-9_]/, "_", local)
                    imp_pkg[f SUBSEP local] = path
                }
            }
        }
    }
}
function path_pkg_name(path,   d, cmd, p) {
    if (path in path_pkg) return path_pkg[path]
    gsub(/github\.com\/usememos\/memos\//, repo "/", path)
    cmd = "awk '/^package /{print $2; exit}' " path "/*.go 2>/dev/null"
    cmd | getline p; close(cmd)
    path_pkg[path] = p
    return p
}
function enclosing(f, ln,   j, q, rp) {
    q = f ":TOPLEVEL"
    for (j = 1; j <= file_nfuncs[f]; j++) {
        if (ln >= file_func_start[f,j]) {
            rp = file_func_recv[f,j]
            q = f ":" file_func_pkg[f,j] "."
            if (rp != "") q = q rp "."
            q = q file_func_name[f,j]
        }
    }
    return q
}
function record_call(q, f, ln,   c) {
    if (sym_file[q] == f && ln == sym_start[q]) return
    c = enclosing(f, ln)
    if (!(q SUBSEP c in seen_caller)) { seen_caller[q SUBSEP c] = 1; fanin_c[q]++ }
    fanin_s[q]++
}
function scan_qualified(f, line, ln,   pos, chunk, local, fname, k, ipath, ipkg, key) {
    pos = 1
    while (pos <= length(line)) {
        chunk = substr(line, pos)
        if (!match(chunk, /[A-Za-z0-9_]+\.[A-Za-z0-9_]+[ \t]*\(/)) break
        full = substr(chunk, RSTART, RLENGTH)
        split(full, bits, ".")
        local = bits[1]
        fname = bits[2]
        sub(/[ \t]*\(.*/, "", fname)
        pos = pos + RSTART + RLENGTH - 1
        for (k in imp_pkg) {
            split(k, kk, SUBSEP)
            if (kk[1] != f) continue
            if (kk[2] != local) continue
            ipath = imp_pkg[k]
            ipkg = path_pkg_name(ipath)
            key = ipkg SUBSEP fname
            if (key in pkg_func) record_call(pkg_func[key], f, ln)
        }
    }
}
function scan_unqualified(f, line, ln, cpkg, fdir,   q, fname) {
    for (q in is_internal) {
        if (sym_recv[q] != "") continue
        if (index(sym_file[q], fdir "/") != 1) continue
        if (sym_pkg[q] != cpkg) continue
        fname = sym_name[q]
        if (index(line, fname "(") > 0 || index(line, fname "\t(") > 0) {
            if (index(line, "." fname "(") > 0) continue
            if (index(line, "func " fname "(") == 1) continue
            record_call(q, f, ln)
        }
    }
}
function scan_methods(f, line, ln,   pos, chunk, mname, j, q, rtype) {
    pos = 1
    while (pos <= length(line)) {
        chunk = substr(line, pos)
        if (!match(chunk, /\.[A-Za-z0-9_]+[ \t]*\(/)) break
        full = substr(chunk, RSTART+1, RLENGTH-1)
        sub(/[ \t]*\(.*/, "", full)
        mname = full
        pos = pos + RSTART + RLENGTH - 1
        if (!(mname in mc)) continue
        if (mc[mname] == 1) {
            q = mlist[mname SUBSEP 1]
            record_call(q, f, ln)
        } else {
            for (j = 1; j <= mc[mname]; j++) {
                q = mlist[mname SUBSEP j]
                rtype = sym_recv[q]
                if (index(line, rtype) > 0) record_call(q, f, ln)
            }
        }
    }
}
END {
    for (fi = 1; fi <= nfiles; fi++) {
        f = files[fi]
        read_file(f); parse_decls(f); parse_imports(f)
    }
    for (fi = 1; fi <= nfiles; fi++) {
        f = files[fi]
        if (f ~ repo "/internal/") {
            d = f; sub(/\/[^\/]+$/, "", d)
            rel = d; sub("^" repo "/", "", rel)
            path_pkg["github.com/usememos/memos/" rel] = file_pkg[f]
        }
    }
    for (fi = 1; fi <= nfiles; fi++) {
        f = files[fi]
        read_file(f)
        cpkg = file_pkg[f]
        fdir = f; sub(/\/[^\/]+$/, "", fdir)
        for (i = 1; i <= nlines; i++) {
            if (lines[i] ~ /^func /) continue
            scan_qualified(f, lines[i], i)
            scan_unqualified(f, lines[i], i, cpkg, fdir)
            scan_methods(f, lines[i], i)
        }
    }
    nout = 0
    for (q in is_internal) if (fanin_c[q] > 0) {
        out[++nout] = sprintf("%05d|%05d|%s|%s", fanin_c[q], fanin_s[q], q, sym_file[q])
    }
    for (i = 1; i <= nout; i++) for (j = i+1; j <= nout; j++) {
        split(out[i], ai, "|"); split(out[j], aj, "|")
        if (aj[1] > ai[1] || (aj[1] == ai[1] && aj[2] > ai[2])) { tmp = out[i]; out[i] = out[j]; out[j] = tmp }
    }
    print "=== TOP 40 BY DISTINCT CALLERS (FAN-IN) ==="
    max = (nout < 40 ? nout : 40)
    for (i = 1; i <= max; i++) {
        split(out[i], a, "|")
        print a[1]+0 " callers | " a[2]+0 " sites | " a[3] " | " a[4]
    }
    print "\nTotal internal symbols: " length(is_internal)
    print "Symbols with >=1 caller: " nout
    if (nout > 0) {
        split(out[1], top, "|")
        print "\nTOP=" top[3]
    }
}

