+        if (!match(chunk, /[A-Za-z0-9_]+\.[A-Za-z0-9_]+[ \t]*\(/)) break
+        full = substr(chunk, RSTART, RLENGTH)
+        split(full, bits, ".")
+        local = bits[1]
+        fname = bits[2]
+        sub(/[ \t]*\(.*/, "", fname)
+        pos = pos + RSTART + RLENGTH - 1
+        for (k in imp_pkg) {
+            split(k, kk, SUBSEP)
+            if (kk[1] != f) continue
+            if (kk[2] != local) continue
+            ipath = imp_pkg[k]
+            ipkg = path_pkg_name(ipath)
+            key = ipkg SUBSEP fname
+            if (key in pkg_func) record_call(pkg_func[key], f, ln)
+        }
+    }
+}
+function scan_unqualified_pkgfunc(f, line, ln, cpkg, fdir,   q, fname) {
+    for (q in is_internal) {
+        if (sym_recv[q] != "") continue
+        if (sym_dir[q] != fdir) continue
+        if (sym_pkg[q] != cpkg) continue
+        fname = sym_name[q]
+        if (index(line, fname "(") > 0 || index(line, fname "\t(") > 0) {
+            if (index(line, "." fname "(") > 0) continue
+            if (index(line, "func " fname "(") == 1) continue
+            record_call(q, f, ln)
+        }
+    }
+}
+function method_ok(q, f, line,   mname, rtype, dp) {
+    mname = sym_name[q]
+    rtype = sym_recv[q]
+    dp = sym_dir[q]
+    # Same package directory tree: allow if receiver type or lowercase var hint
+    if (file_dir[f] == dp) return 1
+    # Cross-package: require import of declaring package
+    if (!file_imports_pkg(f, sym_pkg[q])) return 0
+    # For common names, require receiver type token on line
+    if (mname in common) {
+        if (index(line, rtype) > 0) return 1
+        if (index(line, "schedule.") > 0 && rtype == "Schedule") return 1
+        return 0
+    }
+    # Uncommon name but unique: still require import (already checked)
+    if (mc[mname] == 1) return 1
+    # Ambiguous: require receiver type on line
+    if (index(line, rtype) > 0) return 1
+    return 0
+}
+function scan_methods(f, line, ln,   pos, chunk, mname, j, q) {
+    pos = 1
+    while (pos <= length(line)) {
+        chunk = substr(line, pos)
+        if (!match(chunk, /\.[A-Za-z0-9_]+[ \t]*\(/)) break
+        full = substr(chunk, RSTART+1, RLENGTH-1)
+        sub(/[ \t]*\(.*/, "", full)
+        mname = full
+        pos = pos + RSTART + RLENGTH - 1
+        if (!(mname in mc)) continue
+        for (j = 1; j <= mc[mname]; j++) {
+            q = mlist[mname SUBSEP j]
+            if (method_ok(q, f, line)) record_call(q, f, ln)
+        }
+    }
+}
+END {
+    for (fi = 1; fi <= nfiles; fi++) {
+        f = files[fi]
+        read_file(f); parse_decls(f); parse_imports(f)
+    }
+    for (fi = 1; fi <= nfiles; fi++) {
+        f = files[fi]
+        if (f ~ repo "/internal/") {
+            d = f; sub(/\/[^\/]+$/, "", d)
+            rel = d; sub("^" repo "/", "", rel)
+            path_pkg["github.com/usememos/memos/" rel] = file_pkg[f]
+        }
+    }
+    for (fi = 1; fi <= nfiles; fi++) {
+        f = files[fi]
+        read_file(f)
+        cpkg = file_pkg[f]
+        fdir = file_dir[f]
+        for (i = 1; i <= nlines; i++) {
+            if (lines[i] ~ /^func /) continue
+            scan_qualified(f, lines[i], i)
+            scan_unqualified_pkgfunc(f, lines[i], i, cpkg, fdir)
+            scan_methods(f, lines[i], i)
+        }
+    }
+    nout = 0
+    for (q in is_internal) if (fanin_c[q] > 0) {
+        out[++nout] = sprintf("%05d|%05d|%s|%s", fanin_c[q], fanin_s[q], q, sym_file[q])
+    }
+    for (i = 1; i <= nout; i++) for (j = i+1; j <= nout; j++) {
+        split(out[i], ai, "|"); split(out[j], aj, "|")
+        if (aj[1] > ai[1] || (aj[1] == ai[1] && aj[2] > ai[2])) { tmp = out[i]; out[i] = out[j]; out[j] = tmp }
+    }
+    print "=== TOP 40 BY DISTINCT CALLERS (FAN-IN) ==="
+    max = (nout < 40 ? nout : 40)
+    for (i = 1; i <= max; i++) {
+        split(out[i], a, "|")
+        print a[1]+0 " callers | " a[2]+0 " sites | " a[3] " | " a[4]
+    }
+    print "\nTotal internal symbols: " length(is_internal)
+    print "Symbols with >=1 caller: " nout
+    if (nout > 0) {
+        split(out[1], top, "|")
+        print "\nTOP=" top[3]
+        tq = top[3]
+        print "Callers for top symbol:"
+        for (k in seen_caller) {
+            split(k, kk, SUBSEP)
+            if (kk[1] == tq) print "  " kk[2]
+        }
+    }
+}

