            if (match(lines[i], /^func \([^)]*\)[[:space:]]+[A-Za-z0-9_]+/)) {
                chunk=lines[i]; sub(/^func \(/, "", chunk); sub(/\).*/, "", chunk); split(chunk,a,")"); rest=a[2]; sub(/^[ \t]+/,"",rest); split(rest,w,/[( \t]+/); cur=w[1]
            } else { sub(/^func /,"",lines[i]); split(lines[i],w,/[( \t]+/); cur=w[1] }
            cstart=i
        }
        if (index(lines[i], "addArg(")>0 && lines[i] !~ /^func /) print i ": " cur
    }
}
'

